func TestEnumStoreProbeCheckOutcome(t *testing.T) {
	t.Run("NewFromString_passed", func(t *testing.T) {
		t.Parallel()
		val, err := NewStoreProbeCheckOutcomeFromString("passed")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, StoreProbeCheckOutcome("passed"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_unsupported", func(t *testing.T) {
		t.Parallel()
		val, err := NewStoreProbeCheckOutcomeFromString("unsupported")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, StoreProbeCheckOutcome("unsupported"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_failed", func(t *testing.T) {
		t.Parallel()
		val, err := NewStoreProbeCheckOutcomeFromString("failed")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, StoreProbeCheckOutcome("failed"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewStoreProbeCheckOutcomeFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewStoreProbeCheckOutcomeFromString("passed")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

